import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/structure/commands.md","filePath":"en/modules/structure/commands.md","lastUpdated":0}`),a={name:`en/modules/structure/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to “Commands &amp; Permissions”">​</a></h1><p>Root command <code>/emakistructure</code>, aliases <code>/ems</code> and <code>/estruct</code>. Running it without a subcommand prints the usage hint; an unknown subcommand points you to <code>/ems help</code></p><h2 id="command-list" tabindex="-1">Command list <a class="header-anchor" href="#command-list" aria-label="Permalink to “Command list”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ems help</code></td><td>none (everyone)</td><td>Print the command help list</td></tr><tr><td><code>/ems get &lt;template&gt; [facing]</code></td><td><code>emakistructure.use</code></td><td>Preview-generate the template 3 blocks in front of you (no journal, no persistence) to test placement</td></tr><tr><td><code>/ems select pos1</code> / <code>pos2</code></td><td><code>emakistructure.edit</code></td><td>Set the first/second selection corner to your current position. Both corners must be in the same world; setting the second corner elsewhere reports a world mismatch</td></tr><tr><td><code>/ems select adjust &lt;add|reduce&gt; &lt;front|back|left|right|up|down&gt; &lt;amount&gt;</code></td><td><code>emakistructure.edit</code></td><td>Grow or shrink the selection along that direction; shrinking past the limit reports &quot;shrink too far&quot;</td></tr><tr><td><code>/ems select clear</code></td><td><code>emakistructure.edit</code></td><td>Clear the current selection and its highlight</td></tr><tr><td><code>/ems structure export &lt;name&gt;</code></td><td><code>emakistructure.edit</code></td><td>Export the current selection as structure template <code>structures/&lt;name&gt;.nbt</code> (a vanilla <code>.nbt</code> structure file, not a multiblock definition)</td></tr><tr><td><code>/ems structure place &lt;template&gt; &lt;facing&gt;</code></td><td><code>emakistructure.edit</code></td><td>Place the structure template at your position; facing values are listed below. For multiblocks use <code>/ems multiblock place</code></td></tr><tr><td><code>/ems multiblock export &lt;id&gt; [force]</code></td><td><code>emakistructure.edit</code></td><td>Export the selection as multiblock layout <code>multiblocks/&lt;id&gt;.yml</code> (records only, places nothing). Existing ids require <code>force</code> to overwrite</td></tr><tr><td><code>/ems multiblock place &lt;id&gt; [facing]</code></td><td><code>emakistructure.edit</code></td><td>Place the multiblock definition at your position: vanilla blocks, custom blocks, and furniture members are placed by facing, then forming detection runs automatically</td></tr><tr><td><code>/ems multiblock list</code></td><td><code>emakistructure.admin</code></td><td>List every loaded multiblock definition with member count, rotation flag, and in-progress/active instance counts</td></tr><tr><td><code>/ems multiblock validate &lt;id&gt;</code></td><td><code>emakistructure.admin</code></td><td>Validate that definition against the world shape, reporting members, unresolvable custom blocks, missing furniture sources, and instance counts</td></tr><tr><td><code>/ems reload</code></td><td><code>emakistructure.reload</code></td><td>Reload configuration, language, and the template cache, echoing the loaded template count</td></tr><tr><td><code>/ems debug ...</code></td><td><code>emakistructure.admin</code></td><td>Forwards to the CoreLib debug command (module filter <code>structure</code>) to manage debug modes and diagnostics</td></tr></tbody></table><h2 id="facing-argument" tabindex="-1">Facing argument <a class="header-anchor" href="#facing-argument" aria-label="Permalink to “Facing argument”">​</a></h2><p><code>get</code>, <code>structure place</code>, and <code>multiblock place</code> accept these 8 values:</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>north</code> / <code>east</code> / <code>south</code> / <code>west</code></td><td>Rotate only, no mirroring</td></tr><tr><td><code>north_mirror</code> / <code>east_mirror</code> / <code>south_mirror</code> / <code>west_mirror</code></td><td>Rotate and mirror</td></tr></tbody></table><p>When omitted, the nearest quadrant of the executor&#39;s own facing is used. An invalid value reports the allowed list</p><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission nodes”">​</a></h2><p>Declared in <code>paper-plugin.yml</code>:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakistructure.use</code></td><td><code>true</code> (all players)</td><td>Preview generation with <code>get</code></td></tr><tr><td><code>emakistructure.edit</code></td><td><code>op</code></td><td>Selection, structure export/place, multiblock export/place</td></tr><tr><td><code>emakistructure.reload</code></td><td><code>op</code></td><td>Reload configuration</td></tr><tr><td><code>emakistructure.admin</code></td><td><code>op</code></td><td>Administration and diagnostics: <code>multiblock list</code> / <code>validate</code>, <code>debug</code>; implies the sub-permissions above</td></tr></tbody></table><p>Tab completion filters subcommands by the sender&#39;s permissions and completes template names, multiblock ids, facing values, and the <code>adjust</code> operation/direction names</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Select a 12x8x12 region</span></span>
<span class="line"><span>/ems select pos1</span></span>
<span class="line"><span>/ems select pos2</span></span>
<span class="line"><span>/ems select adjust add up 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Export as a structure template and preview it</span></span>
<span class="line"><span>/ems structure export village_hub_a</span></span>
<span class="line"><span>/ems get village_hub_a north</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Place facing south</span></span>
<span class="line"><span>/ems structure place village_hub_a south</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Record a multiblock structure (from the selection)</span></span>
<span class="line"><span>/ems multiblock export teleporter</span></span>
<span class="line"><span>/ems multiblock place teleporter east</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Inspect loaded multiblocks</span></span>
<span class="line"><span>/ems multiblock list</span></span>
<span class="line"><span>/ems multiblock validate teleporter</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Reload</span></span>
<span class="line"><span>/ems reload</span></span></code></pre></div><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p><code>structure export</code> writes a <strong>vanilla <code>.nbt</code> structure file</strong> (<code>structures/</code>), while <code>multiblock export</code> writes a <strong>multiblock layout definition</strong> (<code>multiblocks/</code>). The two are not interchangeable, neither on export nor on placement</p></div>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};